#!/usr/bin/env bash
set -euo pipefail
umask 077
test "$(id -un)" = canay
test "$(hostname)" = noron-HP-Elite-Tower-800-G9-Desktop-PC
cd '<gpu-server-home>/experiments/SCI-sparse_normalizer_benchmark/2026-09-28_codex_mta_matched-bottomk-policy/runtime_cohorts/post_reboot_001'
/usr/bin/python3 -B - <<'PY'
REMOTE='<gpu-server-home>/experiments/SCI-sparse_normalizer_benchmark/2026-09-28_codex_mta_matched-bottomk-policy/runtime_cohorts/post_reboot_001'
OLD_SOURCE='2B6A7A75842F5A4DCA34B50B013CE1C98B63A727150D0C3E1D04DAF0C09E5E60'
OLD_CONFIG='0876F92AAB6E3F49D085132CA896F0A6858A62EEBEB5BA8267013DC3A9BD5EED'
NEW_SOURCE='2661B171DEC9AD49D031ACEA65F91F8BCE4C7C1CF8C3E317E3100EFFD8AC6B7C'
ENCODED={'AUTHOR_RUNTIME_STORAGE_OVERRIDE.json': '', 'ENGINEERING_RELEASE.json': '', 'final_config.json': '', 'SOURCE_MANIFEST.json': ''}
import base64, copy, hashlib, json, os, sys, time
from pathlib import Path
run=Path.cwd()
assert str(run)==REMOTE and os.getuid()==__import__('pwd').getpwnam('canay').pw_uid
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest().upper()
assert sha(run/'SOURCE_MANIFEST.json')==OLD_SOURCE and sha(run/'final_config.json')==OLD_CONFIG
for rel in ['admission/DATA_ENV_ADMISSION.json','admission/SMOKE_INPUT_BINDING.json','admission/MAIN_RELEASE.json','supervision','engineering_smoke','matched50']:
 assert not (run/rel).exists(), 'Runtime already admitted:'+rel
payload={name:base64.b64decode(value) for name,value in ENCODED.items()}
newcfg=json.loads(payload['final_config.json']);oldcfg=json.loads((run/'final_config.json').read_text())
comparison=copy.deepcopy(newcfg);comparison['resource_ceiling']['minimum_free_disk_gib']=10
assert comparison==oldcfg
v=os.statvfs(run);free=v.f_bavail*v.f_frsize
assert free>=5*(1024**3)
assert sha(run/'data/cifar-10-python.tar.gz')==newcfg['archive_sha256'].upper()
backup=run/'administrative_amendments/author_storage_001/preimages';backup.mkdir(parents=True,exist_ok=False,mode=0o700)
for rel in ['final_config.json','SOURCE_MANIFEST.json','admission/ENGINEERING_RELEASE.json','admission/ACQUISITION_RECEIPT.json']:
 p=run/rel;dest=backup/p.name
 with dest.open('xb') as f:f.write(p.read_bytes());f.flush();os.fsync(f.fileno())
 os.chmod(dest,0o600)
acq=json.loads((run/'admission/ACQUISITION_RECEIPT.json').read_text())
assert acq['status']=='ARCHIVE_IDENTITY_VERIFIED_BEFORE_DECODE' and acq['source_manifest_sha256']==OLD_SOURCE
acq.update(source_manifest_sha256=NEW_SOURCE,previous_acquisition_receipt_sha256=sha(backup/'ACQUISITION_RECEIPT.json'),
 administrative_storage_override_sha256=hashlib.sha256(payload['AUTHOR_RUNTIME_STORAGE_OVERRIDE.json']).hexdigest().upper(),
 actual_storage_rebinding_unix=time.time(),http_download_during_storage_rebinding=False,
 storage_rebinding_scope='Actually rehash unchanged existing archive and retain all genuine original acquisition/custody attempts; operational config amendment only')
payload['ACQUISITION_RECEIPT.json']=(json.dumps(acq,indent=2)+'\n').encode()
targets={'final_config.json':'final_config.json','SOURCE_MANIFEST.json':'SOURCE_MANIFEST.json',
 'AUTHOR_RUNTIME_STORAGE_OVERRIDE.json':'AUTHOR_RUNTIME_STORAGE_OVERRIDE.json',
 'ENGINEERING_RELEASE.json':'admission/ENGINEERING_RELEASE.json','ACQUISITION_RECEIPT.json':'admission/ACQUISITION_RECEIPT.json'}
for name,rel in targets.items():
 p=run/rel;tmp=p.with_name(p.name+'.author-storage-001.tmp')
 with tmp.open('xb') as f:f.write(payload[name]);f.flush();os.fsync(f.fileno())
 os.chmod(tmp,0o600);os.replace(tmp,p)
sys.path.insert(0,str(run/'src'))
from support import verify_frozen, verify_release, resource_floor
cfg,source=verify_frozen();assert source==NEW_SOURCE
verify_release('acquisition',cfg,source);resource_floor(cfg)
receipt={'status':'ACTUAL_AUTHOR_STORAGE_OVERRIDE_APPLIED_AND_FROZEN_VERIFIED',
 'recorded_unix':time.time(),'physical_run_root':str(run),'actual_free_disk_bytes_before':free,
 'minimum_free_disk_gib':5,'new_output_ceiling_gib':2,'scientific_configuration_unchanged':True,
 'source_manifest_sha256':source,'final_config_sha256':sha(run/'final_config.json'),
 'archive_sha256':sha(run/'data/cifar-10-python.tar.gz'),'archive_bytes':(run/'data/cifar-10-python.tar.gz').stat().st_size,
 'references':{rel:{'sha256':sha(run/rel),'bytes':(run/rel).stat().st_size} for rel in targets.values()},
 'registered_main_authorized':False,'fresh_runtime_admissions_required':True}
out=run/'administrative_amendments/author_storage_001/ACTUAL_STORAGE_OVERRIDE_RECEIPT.json'
with out.open('x') as f:json.dump(receipt,f,indent=2);f.write('\n');f.flush();os.fsync(f.fileno())
os.chmod(out,0o600);print(json.dumps(receipt))

PY
